#!/usr/bin/env node

// Issue #418: the standing numeric-constant lint. The audit lanes (seam inventory, surface
// closure, the frame-economics ratchet) covered a closed list of modules; the arbitrary-bound
// seams in the rest of impl/src had no net. This lint closes the partition: every impl/src
// module is scanned for BOUND-SHAPED numeric constants — integer literals of 1024 and above
// (decimal, underscore or hex spelling) and multiplied KiB/MiB/GiB products — the magnitude
// class every arbitrary bound in the #492 sweep falls into. Values below 1024 collide with
// innocent counts tree-wide (the same boundary the frame-economics ratchet draws), so they are
// pinned behaviorally instead. Comment lines are out of scope: prose documents magnitudes, it
// does not enforce them.
//
// A flagged code line passes only by one of:
//   • reading the registry — the line references FRAME_LIMITS / limits.mjs / the registry's
//     named derivations;
//   • the operator channel — the line reads process.env (an operator-declared override and its
//     declared fallback are the deployment's own admitted form);
//   • a named pragma — `// baton-lint: declared-bound <lane or derivation citation>` on the
//     line, visible and reviewable at the site (the fixture-clock pragma shape);
//   • this file's own exemption table — every entry names its file, its line shape and the
//     resource the constant bounds. A NEW hit outside the table fails the suite, so the
//     inventory can only shrink deliberately.
//
// Protocol vocabulary that is not a bound is never flagged: git file modes and the JSON-RPC
// reserved code range (-32600..-32603).

import { readdirSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';

const REGISTRY_READ = /FRAME_LIMITS|limits\.mjs|WEB_WAIT_DEFAULT_MS/u;
const ENV_PARSE = /process\.env/u;
const PRAGMA = /baton-lint:\s*declared-bound\s+\S/u;
const DECIMAL = /(?<![\w.$])(\d[\d_]*)(?![\w.$])/gu;
const HEX = /(?<![\w.$])0x([\da-f_]+)(?![\w.$])/gu;
const PRODUCT = /(?<![\w.$])(\d[\d_]*)\s*\*\s*1024(?:\s*\*\s*1024)?(?:\s*\*\s*1024)?(?![\w.$])/gu;

const FLOOR = 1024;
const NON_BOUND = new Set(['100644', '100755', '32600', '32601', '32602', '32603']);

function isCommentLine(line) {
  const trimmed = line.trim();
  return trimmed.startsWith('//') || trimmed.startsWith('*') || trimmed.startsWith('/*');
}

function spellValue(raw) {
  return Number(String(raw).replaceAll('_', ''));
}

function flagLine(line) {
  const flags = [];
  for (const match of line.matchAll(DECIMAL)) {
    if (spellValue(match[1]) >= FLOOR) flags.push(match[1]);
  }
  for (const match of line.matchAll(HEX)) {
    if (spellValue(match[1]) >= FLOOR) flags.push(match[0]);
  }
  for (const match of line.matchAll(PRODUCT)) {
    flags.push(match[0].trim());
  }
  return flags.filter((value) => !NON_BOUND.has(String(value).replaceAll('_', '')));
}

