function* walkSourceFiles(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) yield* walkSourceFiles(path);
    else if (entry.name.endsWith('.mjs')) yield path;
  }
}

export function lintNumericConstants(files, { srcDir = null, staleCheck = true } = {}) {
  const findings = [];
  for (const file of files) {
    let content;
    try {
      content = readFileSync(file, 'utf8');
    } catch {
      continue;
    }
    const rel = srcDir === null ? file : relative(srcDir, file);
    if (rel === 'limits.mjs') continue;
    const lines = content.split('\n');
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index];
      if (isCommentLine(line)) continue;
      if (REGISTRY_READ.test(line) || ENV_PARSE.test(line) || PRAGMA.test(line)) continue;
      const flagged = flagLine(line);
      if (flagged.length === 0) continue;
      const exempted = EXEMPTIONS.some(([exemptFile, pattern]) => pattern.test(line) && rel === exemptFile);
      if (!exempted) {
        findings.push({
          file: rel, line: index + 1,
          constants: flagged.join(', '),
          reason: 'bound-shaped constant outside the registry — declare it in limits.mjs, read it from the registry, mark the operator env line, add "// baton-lint: declared-bound <citation>", or name it in numeric-constant-lint.mjs\'s exemption table',
        });
      }
    }
  }
  // A table entry nothing matches any more is dead weight: it hides nothing and rots. Fail the
  // lint when an entry's file no longer carries a line the entry names.
  if (srcDir !== null && staleCheck) {
    const contents = new Map();
    for (const file of walkSourceFiles(srcDir)) {
      try {
        contents.set(relative(srcDir, file), readFileSync(file, 'utf8'));
      } catch { /* unreadable file: the scan above already reported nothing for it */ }
    }
    for (const [exemptFile, pattern, note] of EXEMPTIONS) {
      const source = contents.get(exemptFile);
      if (source === undefined || !pattern.test(source)) {
        findings.push({
          file: exemptFile, line: 0,
          constants: String(pattern),
          reason: `stale exemption — ${note} — no line in ${exemptFile} matches any more; delete the entry`,
        });
      }
    }
  }
  return findings;
}

export function lintDefaultSourceDirectory() {
  const srcDir = new URL('../src/', import.meta.url).pathname;
  const files = [...walkSourceFiles(srcDir)];
  return lintNumericConstants(files, { srcDir });
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const findings = lintDefaultSourceDirectory();
  for (const finding of findings) {
    process.stderr.write(`numeric-constant-lint: ${finding.file}:${finding.line}: ${finding.constants} — ${finding.reason}\n`);
  }
  process.exitCode = findings.length === 0 ? 0 : 1;
}
